$ErrorActionPreference='Stop';$root=Split-Path -Parent (Split-Path -Parent $PSScriptRoot);$gate=Join-Path $PSScriptRoot 'xyt-runtime-artifact-gate.ps1';$tmp=Join-Path ([IO.Path]::GetTempPath()) ('xyt-artifact-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $tmp|Out-Null
try{$out=Join-Path ([IO.Path]::GetTempPath()) ('xyt-artifact-out-'+[guid]::NewGuid().ToString('N'));Set-Content (Join-Path $tmp 'P3-01-20260929123456789.json') '{}' ;Set-Content (Join-Path $tmp 'P3-01-20260929123456789.log') '';Set-Content (Join-Path $tmp 'unexpected.tmp') '';& pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass -File $gate -RepositoryRoot $root -RuntimeRoot $tmp *> $out;if($LASTEXITCODE -ne 2){throw 'unknown artifact was not blocked'};Remove-Item (Join-Path $tmp 'unexpected.tmp');& pwsh -NoLogo -NoProfile -ExecutionPolicy Bypass -File $gate -RepositoryRoot $root -RuntimeRoot $tmp;if($LASTEXITCODE -ne 0){throw 'registered artifacts did not pass'};'XYT RUNTIME ARTIFACT GATE SELFTEST: PASS';exit 0}finally{Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue;Remove-Item $out -Force -ErrorAction SilentlyContinue}
